const recommendations={
  'Roblox 1':{level:'AI Foundation 2',advice:'进一步培养空间与逻辑思维，打好编程基础，为后续 AI 学习做好准备'},
  'Scratch 1':{level:'AI Foundation 1',advice:'通过图形化编程建立逻辑与顺序意识，在创作中掌握基础编程概念'},
  'Minecraft 1':{level:'AI Foundation 2',advice:'在方块世界中训练空间规划与问题解决能力，逐步建立编程思维'},
  'Python 1':{level:'AI Explorer 1',advice:'进入文本编程阶段，系统掌握变量、循环与函数，完成独立项目'},
  'Java 1':{level:'AI Builder 1',advice:'建立面向对象与工程化编程基础，为完整软件项目开发做好准备'},
  'C++ 1':{level:'AI Challenger 1',advice:'强化严谨的算法与数据结构能力，为进阶开发和竞赛学习打基础'}
};
const $=id=>document.getElementById(id);
const canvas=$('previewCanvas'),ctx=canvas.getContext('2d');
const logo=new Image(),qr=new Image();
logo.src='data:image/png;base64,';
qr.src='data:image/png;base64,';
logo.onload=draw;qr.onload=draw;
const ids=['studentName','trialName','classTime','teacherName','teacherFeedback','courseSelect','courseLevel','courseAdvice'];
const defaults={studentName:'Scarlett',trialName:'Roblox',teacherName:'Brandon C',teacherFeedback:'Scarlett 的试课进行得很顺利。课上我们认识了 Roblox Studio 的界面与工作区，学习了 Part 的插入与变换（Move / Scale / Rotate 三种基础工具），并了解了材质与颜色属性、Anchor 固定以及网格吸附对齐的用法，她也独立完成了一个简单的场景模型搭建。Scarlett 的动手能力很强，跟随老师的节奏很快，讲解一遍后就能自己在 Studio 中准确找到工具并完成操作，遇到不明白的地方也会主动提问。她在课堂上表现出对创作和搭建的浓厚兴趣。综合来看，Scarlett 已经具备继续系统学习的基础，建议接下来系统学习推荐课程，进一步培养空间与逻辑思维，为后续进入 AI 课程体系做好准备。'};
Object.keys(recommendations).forEach(name=>$('courseSelect').add(new Option(name,name)));
function setDefaultTime(){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());$('classTime').value=d.toISOString().slice(0,16)}
function updateCourse(){const item=recommendations[$('courseSelect').value];$('courseLevel').value=item.level;$('courseAdvice').value=item.advice;draw()}
function rr(x,y,w,h,r,fill,stroke='#0000',line=2){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke!=='#0000'){ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.stroke()}}
function text(value,x,y,size,weight='500',color='#3A372F',align='left',family='"Microsoft YaHei","PingFang SC",sans-serif'){ctx.font=`${weight} ${size}px ${family}`;ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='alphabetic';ctx.fillText(value,x,y)}
function wrap(value,x,y,maxWidth,lineHeight,maxLines,size=38,weight='500',color='#3A372F'){ctx.font=`${weight} ${size}px "Microsoft YaHei","PingFang SC",sans-serif`;ctx.fillStyle=color;ctx.textAlign='left';const lines=[];let line='';for(const ch of [...(value||'')]){const next=line+ch;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=ch}else line=next}if(line)lines.push(line);if(lines.length>maxLines){lines.length=maxLines;let last=lines[maxLines-1];while(ctx.measureText(last+'…').width>maxWidth)last=last.slice(0,-1);lines[maxLines-1]=last+'…'}lines.forEach((item,index)=>ctx.fillText(item,x,y+index*lineHeight));return lines.length}
function formatDate(){const raw=$('classTime').value;if(!raw)return '待填写';const d=new Date(raw);return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日  ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
function draw(){
  ctx.clearRect(0,0,1667,2500);ctx.fillStyle='#fff';ctx.fillRect(0,0,1667,2500);
  text('试课',84,160,92,'400','#FFC824','left','"Yipin Qihang","Microsoft YaHei",sans-serif');
  text('反馈',272,160,92,'400','#FF5B24','left','"Yipin Qihang","Microsoft YaHei",sans-serif');
  text('Trial Class Feedback Report',84,255,29,'700','#6B6760');
  if(logo.complete&&logo.naturalWidth)ctx.drawImage(logo,1160,72,420,107);
  const start=352,row=106,labelX=84,valueX=350,right=1583;
  const rows=[['学生姓名',$('studentName').value||'—'],['试课名称',$('trialName').value||'—'],['日期与时间',formatDate()],['试听课老师',$('teacherName').value||'—']];
  rows.forEach((item,i)=>{const y=start+i*row;ctx.strokeStyle='#EDEAE3';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(84,y);ctx.lineTo(right,y);ctx.stroke();text(item[0],labelX,y+70,37,'800','#3A372F');text(item[1],valueX,y+70,i<2?43:36,i<2?'800':'500',i===1?'#FF5B24':'#1C1B19')});
  ctx.beginPath();ctx.moveTo(84,start+4*row);ctx.lineTo(right,start+4*row);ctx.stroke();
  ctx.strokeStyle='#FFC824';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(84,835);ctx.lineTo(right,835);ctx.stroke();
  text('老师评价',84,907,30,'800','#FF5B24');
  rr(84,947,1499,697,18,'#FFFCF0');
  wrap($('teacherFeedback').value,120,1020,1427,64,9,37,'500','#3A372F');
  ctx.strokeStyle='#FFC824';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(120,1568);ctx.lineTo(165,1568);ctx.stroke();
  text(`试听课老师 ${$('teacherName').value||'—'}`,178,1581,28,'700','#6B6760');
  rr(84,1684,1499,230,18,'#fff','#E7E3DB',2);
  rr(120,1749,210,92,46,'#FFC824');text('★ 课程建议',225,1807,27,'800','#1C1B19','center');
  text('继续学习',368,1769,35,'500','#3A372F');text($('courseSelect').value,535,1769,40,'800','#FF5B24');
  const courseWidth=ctx.measureText($('courseSelect').value).width;
  text(`（馒头AI体系中为 ${$('courseLevel').value||'—'} 级别）`,555+courseWidth,1769,27,'700','#6B6760');
  wrap($('courseAdvice').value,368,1832,1165,50,2,34,'500','#3A372F');
  ctx.strokeStyle='#FFC824';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(84,2208);ctx.lineTo(right,2208);ctx.stroke();
  text('未来已来',84,2335,72,'400','#FFC824','left','"Yipin Qihang","Microsoft YaHei",sans-serif');
  text('育才致远',390,2335,72,'400','#FF5B24','left','"Yipin Qihang","Microsoft YaHei",sans-serif');
  text('K12创客AI学院',84,2420,45,'400','#3A372F','left','"Yipin Qihang","Microsoft YaHei",sans-serif');
  text('扫描二维码',1390,2310,29,'800','#1C1B19','right');text('了解课程详情',1390,2355,29,'800','#FF5B24','right');
  if(qr.complete&&qr.naturalWidth)ctx.drawImage(qr,1420,2268,145,145);
  $('charCount').textContent=$('teacherFeedback').value.length;
}
ids.forEach(id=>$(id).addEventListener('input',id==='courseSelect'?updateCourse:draw));
function showToast(message,isError=false){const toast=$('toast');toast.textContent=message;toast.classList.toggle('error',isError);toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
function safeFileName(name){return (name||'学生').replace(/[\\/:*?"<>|]/g,'-').trim()||'学生'}
function downloadCanvas(){draw();const button=$('downloadBtn');button.disabled=true;button.firstElementChild.textContent='正在生成…';try{canvas.toBlob(blob=>{button.disabled=false;button.firstElementChild.textContent='生成并下载 PNG';if(!blob){showToast('图片生成失败，请刷新页面后重试',true);return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${safeFileName($('studentName').value)}-试课反馈.png`;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);showToast('图片已生成，请查看下载文件夹')},'image/png')}catch(error){button.disabled=false;button.firstElementChild.textContent='生成并下载 PNG';showToast('图片生成失败，请刷新页面后重试',true);console.error(error)}}
$('downloadBtn').addEventListener('click',downloadCanvas);
$('resetBtn').addEventListener('click',()=>{Object.entries(defaults).forEach(([key,value])=>$(key).value=value);$('courseSelect').value='Roblox 1';setDefaultTime();updateCourse()});
setDefaultTime();updateCourse();
document.fonts?.ready.then(draw);

